160	
161	        applyWeatherEffects();
162	
163	        // Provide space for newborn animals.
164	        List<Animal> newAnimals = new ArrayList<>();        
165	        // Let all ants act.
166	        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
167	            Animal animal = it.next();
168	            animal.act(newAnimals,time);
169	            if(! animal.isAlive()) {
170	                it.remove();
171	            }
172	        }
173	
174	        //provide space for new created plants
175	        List<Plant> newPlants = new ArrayList<>();
176	        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
177	            Plant plant = it.next();
178	            plant.act(newPlants);
179	            if(! plant.isAlive()) {
180	                it.remove();
181	            }
182	        }
183	
184	               
185	        // Add the newly born animals and plants to the main lists.
186	        animals.addAll(newAnimals);
187	        plants.addAll(newPlants);
188	
