215	            for(int col = 0; col < field.getWidth(); col++) {
216	                if(rand.nextDouble() <= DINGO_CREATION_PROBABILITY) {
217	                    Location location = new Location(row, col);
218	                    Dingo dingo = new Dingo(true, field, location);
219	                    animals.add(dingo);
220	                }
221	                else if(rand.nextDouble() <= ANT_CREATION_PROBABILITY) {
222	                    Location location = new Location(row, col);
223	                    Ant ant = new Ant(true, field, location);
224	                    animals.add(ant);
225	                }
226	                else if(rand.nextDouble() <= SNAKE_CREATION_PROBABILITY) {
227	                    Location location = new Location(row, col);
228	                    Snake snake = new Snake(true, field, location);
229	                    animals.add(snake);
230	                }
231	                else if(rand.nextDouble() <= RAT_CREATION_PROBABILITY) {
232	                    Location location = new Location(row, col);
233	                    Rat rat = new Rat(true, field, location);
234	                    animals.add(rat);
235	                }
236	                else if(rand.nextDouble() <= EAGLE_CREATION_PROBABILITY) {
237	                    Location location = new Location(row, col);
238	                    Eagle eagle = new Eagle(true, field, location);
239	                    animals.add(eagle);
240	                }
241	                else if(rand.nextDouble() <= EMU_CREATION_PROBABILITY) {
242	                    Location location = new Location(row, col);
243	                    Emu emu = new Emu(true, field, location);
244	                    animals.add(emu);
245	                }
246	                else if(rand.nextDouble() <= ACACIA_CREATION_PROBABILITY) {
247	                    Location location = new Location(row, col);
248	                    Acacia acacia = new Acacia(field, location);
249	                    plants.add(acacia);
250	                }
251	                else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
252	                    Location location = new Location(row, col);
253	                    Grass grass = new Grass(field, location);
254	                    plants.add(grass);
255	                }
256	
257	                // else leave the location empty.
258	            }
259	        }
260	    }

